package com.example.TuVanSinhVien.controller;

import com.example.TuVanSinhVien.config.CustomUserDetails;
import com.example.TuVanSinhVien.entity.*;
import com.example.TuVanSinhVien.repository.SinhVienRepository;
import com.example.TuVanSinhVien.service.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.util.List;

@Controller
@RequestMapping("/student")
public class StudentController {
    private final SinhVienRepository sinhVienRepo;
    private final TicketService ticketService;
    private final AppointmentService appointmentService;
    private final ChatService chatService;
    private final CatalogService catalogService;
    private final NotificationService notificationService;

    private SinhVien getStudentOrThrow(CustomUserDetails userDetails) {
        if (userDetails == null) {
            throw new SecurityException("Vui lòng đăng nhập.");
        }
        return sinhVienRepo.findByTaiKhoan_MaTK(userDetails.getMaTK()).orElseThrow(() -> new IllegalStateException("Không tìm thấy thông tin sinh viên cho tài khoản này."));
    }

    @GetMapping("/dashboard")
    public String dashboard(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        SinhVien sv = getStudentOrThrow(userDetails);
        List<YeuCauTuVan> tickets = ticketService.getStudentTickets(sv.getMaSV());
        List<LichHenTuVan> appointments = appointmentService.getStudentAppointments(sv.getMaSV());
        long processingTickets = tickets.stream().filter(t -> !"Dong".equals(t.getTrangThai())).count();
        long pendingAppointments = appointments.stream().filter(a -> "ChoDuyet".equals(a.getTrangThai()) || "DaXacNhan".equals(a.getTrangThai())).count();
        model.addAttribute("student", sv);
        model.addAttribute("recentTickets", tickets.stream().limit(5).toList());
        model.addAttribute("recentAppointments", appointments.stream().limit(5).toList());
        model.addAttribute("processingTicketsCount", processingTickets);
        model.addAttribute("pendingAppointmentsCount", pendingAppointments);
        model.addAttribute("notifications", notificationService.getUserNotifications(sv.getTaiKhoan().getMaTK()).stream().limit(5).toList());
        return "student/dashboard";
    }

    @GetMapping("/tickets")
    public String myTickets(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        SinhVien sv = getStudentOrThrow(userDetails);
        model.addAttribute("tickets", ticketService.getStudentTickets(sv.getMaSV()));
        return "student/tickets";
    }

    @GetMapping("/tickets/new")
    public String newTicketForm(Model model) {
        model.addAttribute("donViList", catalogService.getAllActiveDonVi());
        model.addAttribute("linhVucList", catalogService.getAllActiveLinhVuc());
        return "student/new-ticket";
    }

    @PostMapping("/tickets/new")
    public String createTicket(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam Integer maDonVi, @RequestParam Integer maLinhVuc, @RequestParam String tieuDe, @RequestParam String noiDung, @RequestParam(required = false) Boolean baoMatDanhTinh, RedirectAttributes redirectAttributes) {
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            YeuCauTuVan ticket = ticketService.createTicket(sv, maLinhVuc, maDonVi, tieuDe, noiDung, baoMatDanhTinh);
            redirectAttributes.addFlashAttribute("successMessage", "Gửi yêu cầu tư vấn thành công! Mã phiếu: #" + ticket.getMaYeuCau());
            return "redirect:/student/tickets/" + ticket.getMaYeuCau();
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
            return "redirect:/student/tickets/new";
        }
    }

    @GetMapping("/tickets/{id}")
    public String ticketDetail(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        SinhVien sv = getStudentOrThrow(userDetails);
        YeuCauTuVan ticket = ticketService.getTicketById(id);
        if (ticket == null || !ticket.getSinhVien().getMaSV().equals(sv.getMaSV())) {
            return "redirect:/student/tickets";
        }
        model.addAttribute("ticket", ticket);
        model.addAttribute("student", sv);
        return "student/ticket-detail";
    }

    @PostMapping("/tickets/{id}/follow-up")
    public String followUpTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String noiDung, RedirectAttributes redirectAttributes) {
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            ticketService.studentFollowUp(id, sv.getTaiKhoan(), noiDung);
            redirectAttributes.addFlashAttribute("successMessage", "Đã gửi câu hỏi bổ sung tới cố vấn!");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/student/tickets/" + id;
    }

    @PostMapping("/tickets/{id}/close")
    public String closeTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam(required = false) String ketLuan, RedirectAttributes redirectAttributes) {
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            ticketService.closeTicket(id, sv.getTaiKhoan(), ketLuan);
            redirectAttributes.addFlashAttribute("successMessage", "Đã đóng phiếu tư vấn.");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/student/tickets/" + id;
    }

    @PostMapping("/tickets/{id}/rate")
    public String rateTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam Short soSao, @RequestParam(required = false) String nhanXet, RedirectAttributes redirectAttributes) {
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            ticketService.rateTicket(id, sv.getMaSV(), soSao, nhanXet);
            redirectAttributes.addFlashAttribute("successMessage", "Cảm ơn bạn đã gửi đánh giá chất lượng tư vấn!");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/student/tickets/" + id;
    }

    @GetMapping("/appointments")
    public String appointments(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam(required = false) Integer maCV, Model model) {
        SinhVien sv = getStudentOrThrow(userDetails);
        model.addAttribute("appointments", appointmentService.getStudentAppointments(sv.getMaSV()));
        model.addAttribute("availableSlots", appointmentService.getAvailableSlots(maCV));
        model.addAttribute("advisors", catalogService.getAllActiveAdvisors());
        model.addAttribute("selectedCv", maCV);
        return "student/appointments";
    }

    @PostMapping("/appointments/book")
    public String bookAppointment(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam Integer maKhungGio, @RequestParam String chuDe, @RequestParam String noiDungHen, RedirectAttributes redirectAttributes) {
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            appointmentService.bookAppointment(sv, maKhungGio, chuDe, noiDungHen);
            redirectAttributes.addFlashAttribute("successMessage", "Đặt lịch hẹn tư vấn thành công! Vui lòng chờ cố vấn xét duyệt.");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/student/appointments";
    }

    @PostMapping("/appointments/{id}/cancel")
    public String cancelAppointment(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String lyDo, RedirectAttributes redirectAttributes) {
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            appointmentService.cancelAppointment(id, sv.getMaSV(), lyDo);
            redirectAttributes.addFlashAttribute("successMessage", "Đã hủy lịch hẹn tư vấn thành công.");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/student/appointments";
    }

    @PostMapping("/appointments/{id}/rate")
    public String rateAppointment(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam Short soSao, @RequestParam(required = false) String nhanXet, RedirectAttributes redirectAttributes) {
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            appointmentService.rateAppointment(id, sv.getMaSV(), soSao, nhanXet);
            redirectAttributes.addFlashAttribute("successMessage", "Cảm ơn bạn đã đánh giá buổi tư vấn!");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/student/appointments";
    }

    @GetMapping("/chat")
    public String chatPage(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam(required = false) Integer maDonVi, Model model) {
        SinhVien sv = getStudentOrThrow(userDetails);
        List<DonVi> donViList = catalogService.getAllActiveDonVi();
        model.addAttribute("donViList", donViList);
        Integer targetDonVi = (maDonVi != null) ? maDonVi : (donViList.isEmpty() ? null : donViList.get(0).getMaDonVi());
        if (targetDonVi != null) {
            PhienChat session = chatService.getOrCreateSession(sv, targetDonVi);
            model.addAttribute("currentSession", session);
            model.addAttribute("messages", chatService.getMessages(session.getMaPhienChat()));
            model.addAttribute("selectedDonVi", targetDonVi);
        }
        model.addAttribute("student", sv);
        return "student/chat";
    }

    @PostMapping("/chat/{sessionId}/send")
    public String sendChatMessage(@PathVariable Integer sessionId, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String noiDung, RedirectAttributes redirectAttributes) {
        Integer maDonVi = null;
        try {
            SinhVien sv = getStudentOrThrow(userDetails);
            TinNhanChat msg = chatService.sendMessage(sessionId, sv.getTaiKhoan(), noiDung, "VanBan");
            maDonVi = msg.getPhienChat().getDonVi().getMaDonVi();
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/student/chat" + (maDonVi != null ? "?maDonVi=" + maDonVi : "");
    }

    @GetMapping("/history")
    public String history(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        SinhVien sv = getStudentOrThrow(userDetails);
        model.addAttribute("tickets", ticketService.getStudentTickets(sv.getMaSV()));
        model.addAttribute("appointments", appointmentService.getStudentAppointments(sv.getMaSV()));
        return "student/history";
    }

    @java.lang.SuppressWarnings("all")
    @lombok.Generated
    public StudentController(final SinhVienRepository sinhVienRepo, final TicketService ticketService, final AppointmentService appointmentService, final ChatService chatService, final CatalogService catalogService, final NotificationService notificationService) {
        this.sinhVienRepo = sinhVienRepo;
        this.ticketService = ticketService;
        this.appointmentService = appointmentService;
        this.chatService = chatService;
        this.catalogService = catalogService;
        this.notificationService = notificationService;
    }
}
